import React from "react";

function InfoField({
  icon,
  label,
  value,
  children,
  valueClassName = "",
  action,
}) {
  return (
    <div className="d-flex align-items-center gap-3 border rounded-4 px-3 py-3 mb-3 bg-white">
      <div
        className="text-primary flex-shrink-0"
        style={{ opacity: 0.75 }}
      >
        {icon}
      </div>

      <span className="text-muted flex-shrink-0">
        {label}:
      </span>

      <div className="d-flex align-items-center gap-2 flex-grow-1">
        {children ? (
          children
        ) : (
          <span className={`text-dark ${valueClassName}`}>
            {value}
          </span>
        )}
      </div>

      {action && (
        <div className="flex-shrink-0">
          {action}
        </div>
      )}
    </div>
  );
}

export default InfoField;
